1	export type Item = { type: string };
2	export type Step = { op: string; items?: Item[] };
3	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
4	
5	export type StepResult = { premium: number };
6	export type ScenarioResult = { results: StepResult[] };
7	
8	const BASE_PREMIUMS: Record<string, number> = {
9	  sword: 100,
10	  amulet: 60,
11	  staff: 80,
12	  potion: 40,
13	  rune: 25,
14	  moonstone: 25,
15	};
16	
17	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
18	const PROCESSING_FEE = 5;
19	
20	const BLOCK_SIZE = 3;
21	const BLOCK_BASE_PREMIUM = 60;
22	
23	const countByType = (items: Item[]): Map<string, number> => {
24	  const counts = new Map<string, number>();
25	  for (const item of items) {
26	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
27	  }
28	  return counts;
29	};
30	
31	const basePremiumForType = (type: string, count: number): number =>
32	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
33	
34	const policyBasePremium = (items: Item[]): number => {
35	  let total = 0;
36	  for (const [type, count] of countByType(items)) {
37	    total += basePremiumForType(type, count);
38	  }
39	  return total;
40	};
41	
42	const quotePremium = (items: Item[] = []): number => {
43	  const policyBase = policyBasePremium(items);
44	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
45	  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
46	};
47	
48	export const runScenario = (scenario: Scenario): ScenarioResult => ({
49	  results: scenario.steps.map((step) => ({
50	    premium: quotePremium(step.items),
51	  })),
52	});
